export const title = "How to Check Whether a Keyboard Tray Fits a Curved or Beveled Desk Edge";
export const metaTitle = "How to Check Whether a Keyboard Tray Fits a";
export const metaDescription = "Inspect a side profile and top view of the desk, identify the flat contact areas above and below, and compare those areas with the complete clamp.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-11-10";
export const readTime = "11 min";
